"""In-depth learning content per phishing type: group, channel, checklist, detection queries, analyst mistakes."""

GROUPS = {"email": "Email & calendar", "mobile": "Mobile & voice", "web": "Web & network", "social": "Social"}


def q(name, kql, spl):
    return {"name": name, "kql": kql, "spl": spl}


